import java.util.List;
import java.util.stream.Collectors;

public record Order(String id, double amount, String status) {}

public class ImmutablePipelineService {
    public List<String> processActiveOrders(List<Order> rawOrders) {
        if (rawOrders == null) {
            return List.of();
        }
        return rawOrders.stream()
            .filter(order -> "ACTIVE".equalsIgnoreCase(order.status()))
            .map(order -> order.id().toUpperCase())
            .sorted()
            .collect(Collectors.toUnmodifiableList());
    }
}
